mapper.select:
SELECT * FROM mcp_server WHERE name = #{name} AND active = 1

    AND tenant_id = #{tenantId}

LIMIT 1

mapper.insert:
INSERT INTO mcp_server (
tenant_id, name, description, type, command, url, auth_type, oauth_config, status, is_public, creator, active, create_time, update_time, headers, env_params
) VALUES (
#{tenantId}, #{name}, #{description}, #{type}, #{command}, #{url}, #{authType}, #{oauthConfig}, #{status}, #{isPublic}, #{creator}, #{active},
#{createTime}, #{updateTime}, #{headers}, #{envParams}
)

mapper.select:
SELECT * FROM mcp_server
WHERE active = 1
AND (is_public = 1 OR creator = #{currentUsername})

    AND (name LIKE CONCAT('%', #{keyword}, '%')
    OR description LIKE CONCAT('%', #{keyword}, '%'))


    AND status = #{status}


    AND type = #{type}


    AND tenant_id = #{tenantId}

ORDER BY status DESC, update_time DESC
